dtsPropsFor.Button:
variant?: "primary" | "outline" | "ghost" | "link" | "checkout";
size?: "sm" | "md" | "lg" | "full";
children: React.ReactNode;
type?: "button" | "submit" | "reset";
disabled?: boolean;
className?: string;

dtsPropsFor.ButtonLink:
href: string;
variant?: "primary" | "outline" | "ghost" | "link" | "checkout";
size?: "sm" | "md" | "lg" | "full";
children: React.ReactNode;
className?: string;
target?: string;
rel?: string;

dtsPropsFor.Wordmark:
className?: string;
/** Use the cream artwork, for espresso and taupe surfaces. */
onDark?: boolean;
/** Horizontal is the default everywhere; stacked is for narrow or square space. */
variant?: "horizontal" | "stacked";
/** Rendered height in px; the lockup keeps its ratio. */
height?: number;

dtsPropsFor.Price:
price: { amount: string; currencyCode: "IDR" | "USD" } | null;
/** The was-price, when the piece is marked down. */
compareAt?: { amount: string; currencyCode: "IDR" | "USD" } | null;
className?: string;
/** `display` is the product page's Playfair treatment. */
size?: "small" | "display";

dtsPropsFor.Media:
image: { url: string | null; altText: string; width: number; height: number };
/** Responsive sizes string the layout uses; required for real images. */
sizes: string;
/** CSS aspect ratio, e.g. "1 / 1". Defaults to the image's own. */
ratio?: string;
/** Fill the positioned ancestor instead of holding a ratio. */
fill?: boolean;
priority?: boolean;
className?: string;
/** Caption shown on the placeholder block. */
label?: string;

dtsPropsFor.ProductCard:
product: {
  id: string;
  handle: string;
  title: string;
  material: string;
  description: string;
  care: string;
  productType: string;
  tags: string[];
  featuredImage: { url: string | null; altText: string; width: number; height: number };
  images: { url: string | null; altText: string; width: number; height: number }[];
  priceRange: { minVariantPrice: { amount: string; currencyCode: "IDR" | "USD" } | null };
  compareAtPrice: { amount: string; currencyCode: "IDR" | "USD" } | null;
  options: { name: string; values: { name: string; available: boolean; swatch?: string }[] }[];
  variants: {
    id: string;
    title: string;
    selectedOptions: { name: string; value: string }[];
    availableForSale: boolean;
    price: { amount: string; currencyCode: "IDR" | "USD" } | null;
    compareAtPrice: { amount: string; currencyCode: "IDR" | "USD" } | null;
  }[];
  availableForSale: boolean;
};
sizes: string;
/** Set so the card's name never skips a heading level on the page it sits on. */
headingLevel?: "h2" | "h3";

dtsPropsFor.CatalogueFilters:
facets: {
  categories: { name: string; count: number }[];
  sizes: string[];
  colours: { name: string; swatch?: string }[];
  madeToOrderCount: number;
  total: number;
};
query: {
  /** Category is single-select, the way the design's sidebar reads. */
  category: string | null;
  sizes: string[];
  colours: string[];
  madeToOrder: boolean;
  inStockOnly: boolean;
  sort: "featured" | "price-asc" | "price-desc";
  page: number;
};
